corrected_code:
namespace App\Http\Resources;

use Illuminate\Http\Request;
use Illuminate\Http\Resources\Json\JsonResource;

class PrescriptionResource extends JsonResource
{
    public function toArray(Request $request): array
    {
        $isClinician = $request->user()?->hasRole(['physician', 'pharmacist']);

        return [
            'id' => $this->id,
            'medication' => $this->medication_name,
            'dosage' => $this->dosage,
            'prescriber_dea_number' => $this->when($isClinician, $this->doctor->dea_registration_number),
            'internal_risk_assessment' => $this->when($isClinician, $this->internal_risk_notes),
            'override_justification' => $this->when($isClinician, $this->pharmacy_override_code)
        ];
    }
}
